let orderReport=null;
const orderRoles=['order_id','team','ordered_on','due_on','delivered_on'];
const orderAction=(message,fn)=>run(message,fn,'orders-notice');
function orderSourceList(rows){const el=$('orders-source'),old=el.value;el.innerHTML='<option value="">Choose a saved CSV</option>'+rows.map(r=>`<option value="${esc(r.id)}">${esc(r.name)}</option>`).join('');el.value=old;}
async function orderLists(){orderSourceList(await api('/api/datasets'));const rows=await api('/api/order-runs'),el=$('orders-history'),old=el.value;el.innerHTML='<option value="">Choose a saved run</option>'+rows.map(r=>`<option value="${esc(r.id)}">${esc(r.source_name)} · ${esc(r.created)}</option>`).join('');el.value=old;}
async function orderColumns(){
  $('orders-contract').checked=false;
  $('orders-mapping').innerHTML='';if(!$('orders-source').value)return;
  const d=await api('/api/dataset/'+$('orders-source').value);
  $('orders-mapping').innerHTML=orderRoles.map(role=>`<div class="field"><label for="orders-map-${role}">${esc(role.replaceAll('_',' '))}</label><select id="orders-map-${role}"><option value="">Choose column</option>${d.report.columns.map((c,i)=>`<option value="${i}">${esc(c.name)}</option>`).join('')}</select></div>`).join('');
}
function renderOrders(){
  const r=orderReport;$('orders-export').hidden=false;
  $('orders-report').innerHTML=`<h3>${esc(r.source_name)} · snapshot ${esc(r.as_of)}</h3><p>${esc(r.note)}</p><div class="stats">${Object.entries(r.counts).map(([k,v])=>`<div class="stat"><strong>${v}</strong><span>${esc(k)}</span></div>`).join('')}</div><h3>Delivery performance among valid records</h3><p>${r.summary.open_overdue} open overdue · ${r.summary.due_today} due today · ${r.summary.upcoming} upcoming. On-time rate uses ${r.summary.delivered} delivered orders only.</p><div class="table-scroll"><table class="result-table"><thead><tr><th>Team</th><th>Delivered</th><th>On time / delivered</th><th>Open overdue</th><th>Median delivery lead time</th></tr></thead><tbody>${r.teams.map(t=>`<tr><td>${esc(t.team)}</td><td>${t.delivered}</td><td>${t.on_time_rate===null?'Not defined':(100*t.on_time_rate).toFixed(1)+'%'} (${t.delivered_on_time}/${t.delivered})</td><td>${t.open_overdue}</td><td>${t.median_lead_days===null?'Not defined':t.median_lead_days+' calendar days'}</td></tr>`).join('')}</tbody></table></div><details><summary>Quarantine · ${r.quarantine.length} records excluded from every summary</summary><p>Showing first 100; the full download includes all excluded source cells.</p>${r.quarantine.slice(0,100).map(x=>`<p>Source record ${x.record}: ${esc(x.reasons.join(' '))}</p><pre>${esc(JSON.stringify(x.raw))}</pre>`).join('')}</details><details><summary>Run provenance</summary><pre>${esc(JSON.stringify({id:r.id,created:r.created,version:r.version,source_sha256:r.source_sha256,headers:r.headers,mapping:r.mapping,contract:r.contract},null,2))}</pre></details><div class="compare-grid"><div><label for="orders-team">Team filter</label><select id="orders-team"><option value="">All teams</option>${r.teams.map((x,i)=>`<option value="${i}">${esc(x.team)}</option>`).join('')}</select></div><div><label for="orders-filter">Status filter</label><select id="orders-filter"><option value="flagged">Late or overdue</option><option value="all">All valid orders</option><option value="open overdue">Open overdue</option><option value="due today">Due today</option><option value="upcoming">Upcoming</option><option value="delivered late">Delivered late</option><option value="delivered on time">Delivered on time</option></select></div></div><div id="orders-queue"></div><label for="orders-record">Order to inspect</label><select id="orders-record"></select><div id="orders-evidence"></div>`;
  $('orders-team').onchange=renderOrderQueue;$('orders-filter').onchange=renderOrderQueue;$('orders-record').onchange=renderOrderEvidence;renderOrderQueue();
}
function renderOrderQueue(){
  const r=orderReport,team=$('orders-team').value,mode=$('orders-filter').value;
  const rows=r.results.filter(x=>(team===''||x.team===r.teams[Number(team)].team)&&(mode==='all'||mode==='flagged'&&x.flags.length||x.status===mode));
  const reviewed=new Set(r.reviews.map(x=>x.record));
  $('orders-evidence').innerHTML='';
  $('orders-record').innerHTML='<option value="">Choose an order</option>'+rows.map(x=>`<option value="${x.record}">${esc(x.order_id)} · ${esc(x.status)} · ${x.late_days} days late${reviewed.has(x.record)?' · reviewed':''}</option>`).join('');
  $('orders-queue').innerHTML=`<p>${rows.length} matching orders. Showing first 100; all are available in the selector and download. Sorted by days late, then due date and ID.</p><div class="table-scroll"><table class="result-table"><thead><tr><th>Order</th><th>Team</th><th>Due</th><th>Status</th><th>Days late</th></tr></thead><tbody>${rows.slice(0,100).map(x=>`<tr><td><button data-order-record="${x.record}">${esc(x.order_id)}</button></td><td>${esc(x.team)}</td><td>${esc(x.due_on)}</td><td>${esc(x.status)}</td><td>${x.late_days}</td></tr>`).join('')}</tbody></table></div>`;
  for(const el of document.querySelectorAll('[data-order-record]'))el.onclick=()=>{$('orders-record').value=el.dataset.orderRecord;renderOrderEvidence();};
}
function renderOrderEvidence(){
  const r=orderReport,record=Number($('orders-record').value),row=r.results.find(x=>x.record===record);if(!row){$('orders-evidence').innerHTML='';return;}
  const history=r.reviews.filter(x=>x.record===record);
  $('orders-evidence').innerHTML=`<h3>${esc(row.order_id)} · source record ${record}</h3><p>Ordered ${esc(row.ordered_on)}; due ${esc(row.due_on)}; ${row.delivered_on?'delivered '+esc(row.delivered_on):'undelivered at snapshot '+esc(r.as_of)}. ${row.late_days} calendar days late; ${row.age_days} calendar days from order to delivery or snapshot.</p><details><summary>Original source cells</summary><pre>${esc(JSON.stringify(r.headers.map((h,i)=>({column:h,value:row.raw[i]})),null,2))}</pre></details><div class="field"><label for="orders-decision">Review decision</label><select id="orders-decision"><option>needs investigation</option><option>confirmed issue</option><option>expected event</option></select><label for="orders-note">Evidence or context (required)</label><textarea id="orders-note" rows="3" maxlength="2000"></textarea></div><button id="orders-review">Append review decision</button><h4>Review history</h4>${history.length?history.map(x=>`<p><strong>${esc(x.decision)}</strong> · ${esc(x.created)}<br>${esc(x.note)}</p>`).join(''):'<p>No decisions yet.</p>'}`;
  $('orders-review').onclick=()=>orderAction('Saving order review…',async()=>{const team=$('orders-team').value,filter=$('orders-filter').value;orderReport=await api('/api/investigation-review',{run_id:r.id,record,decision:$('orders-decision').value,note:$('orders-note').value});renderOrders();$('orders-team').value=team;$('orders-filter').value=filter;renderOrderQueue();$('orders-record').value=String(record);renderOrderEvidence();notice('Review appended; original findings and earlier decisions are preserved.');});
}
$('orders-demo').onclick=()=>orderAction('Loading synthetic commitments…',async()=>{const d=await api('/api/order-demo',{});await orderLists();await refreshDatasets();$('orders-source').value=d.dataset_id;await orderColumns();for(const role of orderRoles)$('orders-map-'+role).value=String(d.mapping[role]);$('orders-date').value=d.as_of;$('orders-contract').checked=false;notice('Sample source ready. Confirm the snapshot contract before running.');});
$('orders-source').onchange=()=>orderAction('Loading order columns…',async()=>{await orderColumns();notice('Choose column mappings and a matching snapshot date.');});
$('orders-run').onclick=()=>orderAction('Checking order commitments…',async()=>{if(!$('orders-contract').checked)throw Error('Confirm the order snapshot contract.');if(!$('orders-source').value)throw Error('Choose a saved source CSV.');const mapping={};for(const role of orderRoles){const el=$('orders-map-'+role);if(!el||el.value==='')throw Error('Map all five fields.');mapping[role]=Number(el.value);}orderReport=await api('/api/order-run',{dataset_id:$('orders-source').value,mapping,as_of:$('orders-date').value,contract:'committed-orders-v1'});await orderLists();$('orders-history').value=orderReport.id;renderOrders();notice('Order investigation saved. Review quarantine exclusions alongside delivery summaries.');});
$('orders-history').onchange=()=>orderAction('Opening saved order investigation…',async()=>{if(!$('orders-history').value)return;orderReport=await api('/api/investigation/'+$('orders-history').value);renderOrders();notice('Saved order investigation reopened.');});
$('orders-export').onclick=()=>{if(!orderReport)return;const url=URL.createObjectURL(new Blob([JSON.stringify(orderReport,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='orders-'+orderReport.id+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
document.addEventListener('datasets-updated',e=>orderSourceList(e.detail));
orderLists().catch(e=>{const el=$('orders-notice');el.className='notice error';el.textContent=e.message;});
